import { reviewedMigrations } from "./migration-safety.mjs";

/** Equivalent to the migration runner, for an authenticated Dashboard SQL Editor. */
export function buildSqlEditorBundle(files = reviewedMigrations()) {
  const chunks = [
    "-- Generated by npm run migrations:export. Run the ENTIRE file in Supabase SQL Editor.",
    "-- Creates only mentor_korat objects. No database password or password reset required.",
    "-- Preserves migration checksums/history; safe to run again after successful completion.",
    "BEGIN;",
    "SELECT pg_advisory_xact_lock(680318411);",
    "CREATE SCHEMA IF NOT EXISTS mentor_korat;",
    "CREATE TABLE IF NOT EXISTS mentor_korat.schema_migrations (version text PRIMARY KEY, checksum text NOT NULL, applied_at timestamptz NOT NULL DEFAULT now());",
    "ALTER TABLE mentor_korat.schema_migrations ENABLE ROW LEVEL SECURITY;",
    "REVOKE ALL ON mentor_korat.schema_migrations FROM PUBLIC,anon,authenticated;",
  ];
  for (const file of files) {
    if (file.sql.includes("$mk_source$"))
      throw new Error("SQL delimiter collision");
    const name = file.name.replaceAll("'", "''");
    chunks.push(`
DO $mk_migration$
BEGIN
  IF EXISTS (SELECT 1 FROM mentor_korat.schema_migrations WHERE version='${name}') THEN
    IF NOT EXISTS (SELECT 1 FROM mentor_korat.schema_migrations WHERE version='${name}' AND checksum='${file.hash}') THEN
      RAISE EXCEPTION 'Applied migration checksum mismatch: ${name}';
    END IF;
  ELSE
    EXECUTE $mk_source$
${file.sql}
$mk_source$;
    INSERT INTO mentor_korat.schema_migrations(version,checksum) VALUES ('${name}','${file.hash}');
  END IF;
END
$mk_migration$;
`);
  }
  chunks.push(
    "REVOKE ALL ON mentor_korat.schema_migrations FROM PUBLIC,anon,authenticated;",
    "COMMIT;",
    "SELECT version, applied_at FROM mentor_korat.schema_migrations ORDER BY version;",
    "",
  );
  return chunks.join("\n");
}
